-- =============================================================================
-- M5 — Requisição de PDV Externo
--
-- Objetivo: PDV parceiro posta um pedido que aparece na aba Logística como
-- card do dia (idêntico à criação interna via Requisicao.page.tsx).
--
-- Mudanças aditivas APENAS — sem DROP, sem ALTER de colunas existentes.
-- NÃO altera fluxo interno (picking, separação, expedição, conferência).
--
-- Estrutura:
--   C.1  — 3 colunas nullable em public.requisicoes
--   C.2  — Índice único parcial de idempotência
--   M5   — RPC criar_requisicao_pdv (SECURITY DEFINER, service_role only)
--
-- Reversibilidade M5:
--   DROP FUNCTION IF EXISTS public.criar_requisicao_pdv(integer, uuid, jsonb);
--   DROP INDEX  IF EXISTS public.uq_requisicoes_pdv_externo;
--   ALTER TABLE public.requisicoes
--     DROP COLUMN IF EXISTS origem,
--     DROP COLUMN IF EXISTS pedido_externo_id,
--     DROP COLUMN IF EXISTS pdv_api_key_id;
--   Requisições já criadas permanecem (Article 7 — auditoria imutável).
-- =============================================================================


-- ── C.1 — Novas colunas em public.requisicoes (nullable, aditivas) ───────────
--
-- origem          — fonte da requisição ('pdv_externo' para cá; NULL = interno)
-- pedido_externo_id — ID opaco do PDV; combinado com api_key_id dá idempotência
-- pdv_api_key_id  — FK para rastreabilidade de qual chave criou (soft-link)
ALTER TABLE public.requisicoes
  ADD COLUMN IF NOT EXISTS origem            text NULL,
  ADD COLUMN IF NOT EXISTS pedido_externo_id text NULL,
  ADD COLUMN IF NOT EXISTS pdv_api_key_id    uuid NULL
    REFERENCES public.pdv_api_keys(id) ON DELETE SET NULL;

COMMENT ON COLUMN public.requisicoes.origem IS
  'Origem da requisição: NULL = interna (ERP), ''pdv_externo'' = criada via API PDV.';
COMMENT ON COLUMN public.requisicoes.pedido_externo_id IS
  'ID opaco do pedido no sistema PDV parceiro. Combinado com pdv_api_key_id '
  'provê idempotência: mesma chave + mesmo ID = retorna requisicao_id existente.';
COMMENT ON COLUMN public.requisicoes.pdv_api_key_id IS
  'FK rastreável para pdv_api_keys — identifica qual chave PDV criou a requisição. '
  'ON DELETE SET NULL: revogar a chave não apaga as requisições criadas por ela.';


-- ── C.2 — Índice único parcial de idempotência ────────────────────────────────
--
-- Garante: mesma chave + mesmo pedido_externo_id → apenas 1 linha em requisicoes.
-- WHERE pedido_externo_id IS NOT NULL: não restringe requisições internas (origem NULL)
-- nem requisições PDV sem ID externo (ex.: pedidos ad-hoc sem referência).
CREATE UNIQUE INDEX IF NOT EXISTS uq_requisicoes_pdv_externo
  ON public.requisicoes (pdv_api_key_id, pedido_externo_id)
  WHERE pedido_externo_id IS NOT NULL;


-- ── M5 — RPC criar_requisicao_pdv ────────────────────────────────────────────
--
-- Espelha o INSERT em Requisicao.page.tsx (linhas 1898-2056):
--   · Cria linha em requisicoes (status='em_fila', enqueued_at=now())
--   · Insere itens em requisicoes_itens com deduplicação por dedupe_key
--   · loja_destino_id = p_loja_id (FK integer; adicionado em 20260618120000)
--   · preparador = '' (sem operador físico ainda — será preenchido no picking)
--
-- Resolução de produto (eixo produto_master_id):
--   · COM produto_master_id → resolve nome canônico de produtos_master.nome
--     (coluna confirmada em types.ts:12074; WHERE ativo=true).
--     id desconhecido/inativo → acumula em v_itens_invalidos.
--   · SEM produto_master_id → fallback: nome_produto do payload obrigatório.
--   · Validação atômica: qualquer id inválido → RETURN erro SEM criar requisição.
--
-- Dedupe key por item: COALESCE(produto_master_id::text, lower(trim(nome_produto)))
-- Garante que duplicatas pelo mesmo produto (via id OU nome) somam quantidades.
--
-- Idempotência:
--   1. SELECT BEFORE INSERT — se já existe requisição com (pdv_api_key_id,
--      pedido_externo_id), retorna {ok:true, duplicado:true, requisicao_id}.
--   2. UNIQUE INDEX (C.2) — defesa em profundidade contra race condition.
--
-- GRANT → service_role APENAS; REVOKE → PUBLIC, anon, authenticated.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.criar_requisicao_pdv(
  p_loja_id    integer,
  p_api_key_id uuid,
  p_payload    jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_key_rec            record;
  v_loja_nome          text;
  v_pedido_externo_id  text;
  v_data_receb         date;
  v_data_pedido        date;
  v_solicitante        text;
  v_subtitle           text;
  v_itens              jsonb;
  v_req_id             integer;
  v_req_existente      integer;
  v_nome_req           text;
  v_item               jsonb;
  v_nome_prod          text;
  v_nome_canonico      text;
  v_quantidade         numeric;
  v_obs                text;
  v_prod_id            integer;
  v_ordem              integer := 0;
  v_n_itens            integer := 0;
  v_dedupe_key         text;
  -- Rastreio de chaves de deduplicação já inseridas
  v_dedupe_vistos      text[]    := ARRAY[]::text[];
  -- Coleta de ids de produto_master inválidos (atômica — nada inserido até validar tudo)
  v_itens_invalidos    integer[] := ARRAY[]::integer[];
  -- Itens resolvidos para o 2º loop (evita re-resolução de nomes)
  v_itens_resolvidos   jsonb     := '[]'::jsonb;
BEGIN

  -- ── 0a) ESCOPO (defesa em profundidade; edge já validou) ─────────────────
  SELECT loja_ids, ativo, revoked_at
    INTO v_key_rec
    FROM public.pdv_api_keys
   WHERE id = p_api_key_id;

  IF NOT FOUND OR NOT v_key_rec.ativo OR v_key_rec.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'chave inválida ou revogada');
  END IF;

  IF NOT (p_loja_id = ANY(v_key_rec.loja_ids)) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'loja fora do escopo da chave');
  END IF;

  -- ── 0b) Resolver nome da loja ─────────────────────────────────────────────
  -- loja_solicitante é TEXT no schema (não FK) — precisa do nome, não do id.
  SELECT nome INTO v_loja_nome
    FROM public.lojas
   WHERE id = p_loja_id;

  IF v_loja_nome IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'loja inexistente: id ' || p_loja_id);
  END IF;

  -- ── 1) Extrair campos do payload ─────────────────────────────────────────
  v_pedido_externo_id := NULLIF(trim(p_payload->>'pedido_externo_id'), '');
  v_data_receb        := COALESCE(
                           (NULLIF(trim(p_payload->>'data_recebimento'), ''))::date,
                           CURRENT_DATE
                         );
  v_data_pedido       := COALESCE(
                           (NULLIF(trim(p_payload->>'data_pedido'), ''))::date,
                           CURRENT_DATE
                         );
  v_solicitante       := COALESCE(NULLIF(trim(p_payload->>'solicitante'), ''), 'Pedido Certo');
  v_subtitle          := NULLIF(trim(p_payload->>'subtitle'), '');
  v_itens             := p_payload->'itens';

  -- ── 2) Validação básica + resolução de produtos (1ª passagem) ────────────
  -- Dois objetivos: (a) validar estrutura de cada item; (b) resolver nomes
  -- canônicos via produtos_master. Tudo ANTES de qualquer INSERT.
  --
  -- v_itens_invalidos acumula ids inválidos → validação atômica ao fim.
  IF v_itens IS NULL
     OR jsonb_typeof(v_itens) <> 'array'
     OR jsonb_array_length(v_itens) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'itens deve ser array não-vazio');
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_itens) LOOP
    v_prod_id    := NULLIF(v_item->>'produto_master_id', '')::integer;
    v_quantidade := NULLIF(v_item->>'quantidade', '')::numeric;
    v_obs        := NULLIF(trim(v_item->>'observacao'), '');

    -- Validar quantidade (falha imediata — estrutura corrompida)
    IF v_quantidade IS NULL OR v_quantidade <= 0 THEN
      RETURN jsonb_build_object(
        'ok',   false,
        'erro', 'item com quantidade inválida (deve ser > 0); produto_master_id='
                || COALESCE(v_prod_id::text, 'NULL')
                || ', nome_produto=' || COALESCE(v_item->>'nome_produto', 'NULL')
      );
    END IF;

    IF v_prod_id IS NOT NULL THEN
      -- Eixo produto_master_id: resolve nome canônico (coluna `nome`, WHERE ativo=true)
      SELECT nome INTO v_nome_canonico
        FROM public.produtos_master
       WHERE id = v_prod_id
         AND ativo = true;

      IF NOT FOUND THEN
        -- Acumula — não retorna imediatamente (validação atômica)
        v_itens_invalidos := v_itens_invalidos || v_prod_id;
        v_nome_canonico   := NULL;
      END IF;
    ELSE
      -- Fallback: exige nome_produto não-vazio do payload
      v_nome_canonico := NULLIF(trim(v_item->>'nome_produto'), '');
      IF v_nome_canonico IS NULL THEN
        RETURN jsonb_build_object(
          'ok',   false,
          'erro', 'item sem produto_master_id nem nome_produto — ao menos um é obrigatório'
        );
      END IF;
    END IF;

    -- Acumular item resolvido (mesmo se prod_id inválido — lista apenas para o 2º loop
    -- quando tudo for válido; inválidos serão pegos antes de chegar ao 2º loop)
    v_itens_resolvidos := v_itens_resolvidos || jsonb_build_object(
      'nome_produto',      v_nome_canonico,
      'quantidade',        v_quantidade,
      'produto_master_id', v_prod_id,
      'observacao',        v_obs
    );
  END LOOP;

  -- ── 2.5) Validação atômica de produtos ───────────────────────────────────
  -- Se qualquer produto_master_id foi inválido/inativo, rejeita TODA a requisição.
  -- O parceiro tem o nosso catálogo master; id desconhecido = dessincronização.
  IF array_length(v_itens_invalidos, 1) IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok',              false,
      'erro',            'produto_master_id inválido(s) ou inativo(s)',
      'itens_invalidos', to_jsonb(v_itens_invalidos)
    );
  END IF;

  -- ── 3) IDEMPOTÊNCIA ──────────────────────────────────────────────────────
  -- SELECT antes do INSERT (inner check; unique index C.2 é defesa em profundidade)
  IF v_pedido_externo_id IS NOT NULL THEN
    SELECT id INTO v_req_existente
      FROM public.requisicoes
     WHERE pdv_api_key_id    = p_api_key_id
       AND pedido_externo_id = v_pedido_externo_id
     LIMIT 1;

    IF FOUND THEN
      RETURN jsonb_build_object(
        'ok',            true,
        'duplicado',     true,
        'requisicao_id', v_req_existente
      );
    END IF;
  END IF;

  -- ── 4) Nome canônico da requisição ───────────────────────────────────────
  -- Espelha o padrão do frontend: "Requisição - <loja> - <DD/MM/YY>"
  v_nome_req := 'Requisição - ' || v_loja_nome || ' - ' || to_char(v_data_receb, 'DD/MM/YY');

  -- ── 5) INSERT requisicoes ─────────────────────────────────────────────────
  -- preparador = '' — não há operador físico na criação externa; será preenchido
  --   no picking/separação pela fábrica.
  -- user_id = NULL — sem auth.uid() externo (A6 do ADR original).
  INSERT INTO public.requisicoes (
    nome, solicitante, preparador,
    loja_solicitante, loja_preparadora,
    data_pedido, data_recebimento,
    status, enqueued_at, user_id,
    subtitle, loja_destino_id,
    origem, pedido_externo_id, pdv_api_key_id
  ) VALUES (
    v_nome_req, v_solicitante, '',
    v_loja_nome, 'Fábrica',
    v_data_pedido, v_data_receb,
    'em_fila', now(), NULL,
    v_subtitle, p_loja_id,
    'pdv_externo', v_pedido_externo_id, p_api_key_id
  )
  RETURNING id INTO v_req_id;

  -- ── 6) INSERT itens (2ª passagem — sobre v_itens_resolvidos) ─────────────
  --
  -- Dedupe key: COALESCE(produto_master_id::text, lower(trim(nome_produto)))
  -- Garante que itens com mesmo produto (por id OU por nome) sejam agrupados.
  --
  -- Duplicata → UPDATE (soma qty, concatena obs):
  --   match por produto_id = v_prod_id (quando tem id) OU lower(nome_produto) (fallback)
  --
  -- quantidade_solicitada é INTEGER no schema → ROUND(v_quantidade)::integer
  FOR v_item IN SELECT * FROM jsonb_array_elements(v_itens_resolvidos) LOOP
    v_nome_prod  := v_item->>'nome_produto';
    v_quantidade := (v_item->>'quantidade')::numeric;
    v_obs        := v_item->>'observacao';    -- já NULLIF'd na 1ª passagem
    v_prod_id    := NULLIF(v_item->>'produto_master_id', '')::integer;
    v_dedupe_key := COALESCE(v_prod_id::text, lower(trim(v_nome_prod)));

    IF v_dedupe_key = ANY(v_dedupe_vistos) THEN
      -- Duplicata: agrega no item existente
      UPDATE public.requisicoes_itens
         SET quantidade_solicitada = quantidade_solicitada + ROUND(v_quantidade)::integer,
             observacao = CASE
               WHEN observacao IS NULL OR observacao = '' THEN v_obs
               WHEN v_obs IS NULL                         THEN observacao
               ELSE observacao || '; ' || v_obs
             END
       WHERE requisicao_id = v_req_id
         AND (
           (v_prod_id IS NOT NULL AND produto_id = v_prod_id)
           OR
           (v_prod_id IS NULL AND lower(nome_produto) = lower(trim(v_nome_prod)))
         );
    ELSE
      -- Novo item
      INSERT INTO public.requisicoes_itens (
        requisicao_id, nome_produto,
        quantidade_solicitada, observacao,
        ordem, produto_id
      ) VALUES (
        v_req_id, v_nome_prod,
        ROUND(v_quantidade)::integer, v_obs,
        v_ordem, v_prod_id
      );
      v_dedupe_vistos := v_dedupe_vistos || v_dedupe_key;
      v_n_itens       := v_n_itens + 1;
      v_ordem         := v_ordem + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',               true,
    'requisicao_id',    v_req_id,
    'loja_solicitante', v_loja_nome,
    'itens_inseridos',  v_n_itens,
    'data_recebimento', v_data_receb
  );
END;
$$;

COMMENT ON FUNCTION public.criar_requisicao_pdv(integer, uuid, jsonb) IS
  'Cria requisição de PDV externo: aparece em Logística como card do dia. '
  'Eixo de item: produto_master_id resolve nome canônico (produtos_master.nome, ativo=true). '
  'Fallback: nome_produto do payload quando sem produto_master_id. '
  'Validação atômica: qualquer id inválido/inativo → RETURN erro com itens_invalidos[]. '
  'Dedupe key: COALESCE(produto_master_id::text, lower(nome_produto)). '
  'status=em_fila, idempotente via (pdv_api_key_id, pedido_externo_id). '
  'Apenas service_role.';

REVOKE EXECUTE ON FUNCTION public.criar_requisicao_pdv(integer, uuid, jsonb)
  FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.criar_requisicao_pdv(integer, uuid, jsonb)
  TO service_role;

/**
 * pdv-movimentacao — API HTTP de Movimentação de Caixas QR para PDV de Terceiros
 *
 * Expõe operações de consulta, entrada e saída de caixas (etiquetas QR) e
 * criação de requisições para PDVs externos.
 *
 * Auth: header x-api-key OU Authorization: Bearer <chave>, validado via RPC
 * validar_pdv_api_key (bcrypt, timing-safe, escopo por loja).
 * Sem JWT: verify_jwt = false no config.toml (auth é por API key própria).
 *
 * Endpoints:
 *   GET  /pdv-movimentacao/etiqueta/:uid  → consultar_etiqueta_pdv (R1/A1)
 *   POST /pdv-movimentacao/entrada        → movimentar_lote_pdv tipo=entrada (R2/A2)
 *   POST /pdv-movimentacao/saida          → movimentar_lote_pdv tipo=saida (R3/A3)
 *   POST /pdv-movimentacao/requisicao     → criar_requisicao_pdv (R4/A4)
 *
 * Spec: .harness/spec/pdv-recebimento-externo/spec.md
 * ADR:  .harness/memory-bank/decisions/ADR-20260625-pdv-movimentacao-externa.md
 */

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

// ─── Constantes ──────────────────────────────────────────────────────────────

const MAX_UIDS_PER_REQUEST = 500

// DESVIO INTENCIONAL (F5): Access-Control-Allow-Origin: '*'
// Esta é uma API server-to-server para PDV parceiro externo.
// Restringir a um domínio Momma bloquearia o terceiro (que opera em domínio próprio).
// Segurança não depende de CORS — depende de x-api-key com bcrypt (RPC validar_pdv_api_key).
// Revisado e aceito pelo security-reviewer (PASS-WITH-WARNINGS, sem blocker).
const CORS_HEADERS: Record<string, string> = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers':
    'authorization, x-client-info, apikey, content-type, x-api-key',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
}

const MAX_ITENS_REQUISICAO = 1000

// ─── Tipos ───────────────────────────────────────────────────────────────────

type BatchBodyOk = { ok: true; loja_id: number; uids: string[] }
type BatchBodyError = { ok: false; error: string; message: string; httpStatus: number }
type BatchBodyResult = BatchBodyOk | BatchBodyError

type RequisicaoItem = {
  /** Obrigatório quando produto_master_id ausente; opcional caso contrário. */
  nome_produto?: string
  quantidade: number
  /** Quando presente, a RPC resolve o nome canônico via produtos_master.nome (ativo=true). */
  produto_master_id?: number
  observacao?: string
}
type RequisicaoBodyOk = {
  ok: true
  loja_id: number
  itens: RequisicaoItem[]
  pedido_externo_id?: string
  data_recebimento?: string
  data_pedido?: string
  solicitante?: string
  subtitle?: string
}
type RequisicaoBodyError = { ok: false; error: string; message: string; httpStatus: number }
type RequisicaoBodyResult = RequisicaoBodyOk | RequisicaoBodyError

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Extrai a API key do request.
 * Aceita: `x-api-key: <chave>` OU `Authorization: Bearer <chave>`.
 * Exportada para testabilidade.
 */
export function extractApiKey(req: Request): string | null {
  const fromHeader = req.headers.get('x-api-key')
  if (fromHeader) return fromHeader

  const authHeader = req.headers.get('authorization') ?? req.headers.get('Authorization')
  if (authHeader?.startsWith('Bearer ')) return authHeader.slice(7)

  return null
}

/** Resposta JSON com headers CORS e Content-Type corretos. */
function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
  })
}

/**
 * Extrai rota e params do path após o nome da função.
 * Exemplo: /functions/v1/pdv-movimentacao/etiqueta/ABC → { route: 'etiqueta', params: ['ABC'] }
 * Exportada para testabilidade (testes sem rede).
 */
export function parseRoute(url: URL): { route: string; params: string[] } {
  const parts = url.pathname.split('/').filter(Boolean)
  const funcIdx = parts.findIndex((p) => p === 'pdv-movimentacao')
  const routeParts = funcIdx >= 0 ? parts.slice(funcIdx + 1) : []
  return {
    route: routeParts[0] ?? '',
    params: routeParts.slice(1),
  }
}

/**
 * Valida o body de uma requisição de entrada/saída.
 * Exportada para testabilidade (testes sem rede).
 */
export function validateBatchBody(body: unknown): BatchBodyResult {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return {
      ok: false,
      error: 'invalid_body',
      message: 'Corpo JSON deve ser um objeto com loja_id e uids',
      httpStatus: 400,
    }
  }

  const b = body as Record<string, unknown>

  if (typeof b.loja_id !== 'number' || !Number.isInteger(b.loja_id)) {
    return {
      ok: false,
      error: 'loja_id_required',
      message: 'loja_id é obrigatório e deve ser um número inteiro',
      httpStatus: 400,
    }
  }

  if (!Array.isArray(b.uids) || b.uids.length === 0) {
    return {
      ok: false,
      error: 'uids_required',
      message: 'uids deve ser um array não-vazio de strings (UIDs de etiquetas)',
      httpStatus: 400,
    }
  }

  if (b.uids.length > MAX_UIDS_PER_REQUEST) {
    return {
      ok: false,
      error: 'too_many_uids',
      message: `Máximo ${MAX_UIDS_PER_REQUEST} UIDs por requisição`,
      httpStatus: 422,
    }
  }

  // F4: valida que cada elemento é string não-vazia (rejeita null, number, etc.)
  if (!b.uids.every((u: unknown) => typeof u === 'string' && u.length > 0)) {
    return {
      ok: false,
      error: 'invalid_uid',
      message: 'Todos os UIDs devem ser strings não-vazias',
      httpStatus: 400,
    }
  }

  return {
    ok: true,
    loja_id: b.loja_id,
    uids: b.uids as string[],
  }
}

/**
 * Valida o body de POST /requisicao.
 * Exportada para testabilidade (testes sem rede).
 */
export function validateRequisicaoBody(body: unknown): RequisicaoBodyResult {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return {
      ok: false,
      error: 'invalid_body',
      message: 'Corpo JSON deve ser um objeto com loja_id e itens',
      httpStatus: 400,
    }
  }

  const b = body as Record<string, unknown>

  if (typeof b.loja_id !== 'number' || !Number.isInteger(b.loja_id)) {
    return {
      ok: false,
      error: 'loja_id_required',
      message: 'loja_id é obrigatório e deve ser um número inteiro',
      httpStatus: 400,
    }
  }

  if (!Array.isArray(b.itens) || b.itens.length === 0) {
    return {
      ok: false,
      error: 'itens_required',
      message: 'itens deve ser um array não-vazio',
      httpStatus: 400,
    }
  }

  if (b.itens.length > MAX_ITENS_REQUISICAO) {
    return {
      ok: false,
      error: 'too_many_itens',
      message: `Máximo ${MAX_ITENS_REQUISICAO} itens por requisição`,
      httpStatus: 422,
    }
  }

  // Valida cada elemento.
  // Regra de identificação: produto_master_id (integer) OU nome_produto (string não-vazia).
  // Se nem um nem outro → 400 item_invalido.
  for (const item of b.itens) {
    if (!item || typeof item !== 'object' || Array.isArray(item)) {
      return {
        ok: false,
        error: 'item_invalido',
        message: 'Cada item deve ser um objeto com (produto_master_id ou nome_produto) e quantidade',
        httpStatus: 400,
      }
    }
    const it = item as Record<string, unknown>

    const hasPmid = typeof it.produto_master_id === 'number' && Number.isInteger(it.produto_master_id)
    const hasNome = typeof it.nome_produto === 'string' && it.nome_produto.trim().length > 0

    if (!hasPmid && !hasNome) {
      return {
        ok: false,
        error: 'item_invalido',
        message:
          'Cada item deve ter produto_master_id (integer) OU nome_produto (string não-vazia)',
        httpStatus: 400,
      }
    }

    if (typeof it.quantidade !== 'number' || it.quantidade <= 0) {
      const ref = hasPmid
        ? `produto_master_id=${it.produto_master_id as number}`
        : `"${it.nome_produto as string}"`
      return {
        ok: false,
        error: 'quantidade_invalida',
        message: `Item ${ref}: quantidade deve ser número > 0`,
        httpStatus: 400,
      }
    }
  }

  return {
    ok: true,
    loja_id: b.loja_id,
    itens: b.itens as RequisicaoItem[],
    pedido_externo_id: typeof b.pedido_externo_id === 'string' ? b.pedido_externo_id : undefined,
    data_recebimento: typeof b.data_recebimento === 'string' ? b.data_recebimento : undefined,
    data_pedido: typeof b.data_pedido === 'string' ? b.data_pedido : undefined,
    solicitante: typeof b.solicitante === 'string' ? b.solicitante : undefined,
    subtitle: typeof b.subtitle === 'string' ? b.subtitle : undefined,
  }
}

// ─── Handler principal (exportado para testes) ────────────────────────────────

/**
 * Handler desacoplado do serve() para permitir testes unitários sem rede.
 * O supabase client é injetado externamente (real ou mock).
 */
export async function handler(
  req: Request,
  // deno-lint-ignore no-explicit-any
  supabase: any,
): Promise<Response> {
  // ── Auth: x-api-key header OU Authorization: Bearer <chave> ──────────────
  const apiKey = extractApiKey(req)
  if (!apiKey) {
    return json(
      {
        error: 'missing_api_key',
        message: 'Autenticação obrigatória: header x-api-key ou Authorization: Bearer <chave>',
      },
      401,
    )
  }

  // ── Validar API key via RPC (bcrypt, timing-safe) ──────────────────────────
  const { data: valResult, error: valError } = await supabase.rpc(
    'validar_pdv_api_key',
    { p_key: apiKey },
  )

  if (valError || !valResult?.ok) {
    return json(
      { error: 'unauthorized', message: 'API key inválida, inativa ou revogada' },
      401,
    )
  }

  const apiKeyId: string = valResult.api_key_id
  const lojaIds: number[] = (valResult.loja_ids ?? []) as number[]

  // ── Roteamento ─────────────────────────────────────────────────────────────
  const url = new URL(req.url)
  const { route, params } = parseRoute(url)

  // GET /etiqueta/:uid ─────────────────────────────────────────────────────
  if (req.method === 'GET' && route === 'etiqueta') {
    const uid = params[0]
    if (!uid) {
      return json(
        { error: 'uid_required', message: 'UID obrigatório no path: /etiqueta/{uid}' },
        400,
      )
    }

    const { data, error } = await supabase.rpc('consultar_etiqueta_pdv', {
      p_uid: uid,
    })

    if (error) {
      // F-04: não vazar internals ao parceiro; detalhe logado server-side
      console.error('[pdv-movimentacao] consultar_etiqueta_pdv error:', error.message)
      return json(
        { error: 'internal_error', message: 'Erro interno ao processar a requisição' },
        500,
      )
    }

    if (!data?.ok) {
      return json(
        { error: 'not_found', message: 'Etiqueta não encontrada', uid },
        404,
      )
    }

    return json(data)
  }

  // POST /entrada ou POST /saida ────────────────────────────────────────────
  if ((route === 'entrada' || route === 'saida') && req.method === 'POST') {
    // Parse body
    let body: unknown
    try {
      body = await req.json()
    } catch {
      return json(
        { error: 'invalid_json', message: 'Corpo deve ser JSON válido' },
        400,
      )
    }

    // Validar corpo
    const validated = validateBatchBody(body)
    if (!validated.ok) {
      return json(
        { error: validated.error, message: validated.message },
        validated.httpStatus,
      )
    }

    const { loja_id, uids } = validated

    // Validar escopo de loja (R6/A6)
    if (!lojaIds.includes(loja_id)) {
      return json(
        {
          error: 'loja_fora_escopo',
          message: `Loja ${loja_id} não está no escopo desta chave`,
          loja_ids_permitidos: lojaIds,
        },
        403,
      )
    }

    // Executar batch via RPC
    const { data, error } = await supabase.rpc('movimentar_lote_pdv', {
      p_loja_id: loja_id,
      p_uids: uids,
      p_tipo: route,         // 'entrada' | 'saida'
      p_api_key_id: apiKeyId,
    })

    if (error) {
      // F-04: não vazar internals ao parceiro; detalhe logado server-side
      console.error('[pdv-movimentacao] movimentar_lote_pdv error:', error.message)
      return json(
        { error: 'internal_error', message: 'Erro interno ao processar a requisição' },
        500,
      )
    }

    return json(data)
  }

  // POST /requisicao ────────────────────────────────────────────────────────
  if (route === 'requisicao' && req.method === 'POST') {
    let body: unknown
    try {
      body = await req.json()
    } catch {
      return json({ error: 'invalid_json', message: 'Corpo deve ser JSON válido' }, 400)
    }

    const validated = validateRequisicaoBody(body)
    if (!validated.ok) {
      return json({ error: validated.error, message: validated.message }, validated.httpStatus)
    }

    // Validar escopo de loja antes de chamar RPC
    if (!lojaIds.includes(validated.loja_id)) {
      return json(
        {
          error: 'loja_fora_escopo',
          message: `Loja ${validated.loja_id} não está no escopo desta chave`,
          loja_ids_permitidos: lojaIds,
        },
        403,
      )
    }

    // Montar payload para a RPC (inclui apenas campos presentes)
    const payload: Record<string, unknown> = {
      itens: validated.itens,
    }
    if (validated.pedido_externo_id !== undefined) payload.pedido_externo_id = validated.pedido_externo_id
    if (validated.data_recebimento !== undefined) payload.data_recebimento = validated.data_recebimento
    if (validated.data_pedido !== undefined) payload.data_pedido = validated.data_pedido
    if (validated.solicitante !== undefined) payload.solicitante = validated.solicitante
    if (validated.subtitle !== undefined) payload.subtitle = validated.subtitle

    const { data, error } = await supabase.rpc('criar_requisicao_pdv', {
      p_loja_id: validated.loja_id,
      p_api_key_id: apiKeyId,
      p_payload: payload,
    })

    if (error) {
      console.error('[pdv-movimentacao] criar_requisicao_pdv error:', error.message)
      return json(
        { error: 'internal_error', message: 'Erro interno ao processar a requisição' },
        500,
      )
    }

    // Mapear retorno da RPC para status HTTP
    if (!data?.ok) {
      // produto_master_id inválido/inativo → 422 com itens_invalidos[]
      if (Array.isArray(data?.itens_invalidos)) {
        return json(data, 422)
      }
      // Erros de escopo (chave/loja) → 403; demais → 422
      const isScope =
        typeof data?.erro === 'string' &&
        (data.erro.includes('escopo') ||
          data.erro.includes('inválida') ||
          data.erro.includes('revogada'))
      return json(data, isScope ? 403 : 422)
    }

    return json(data) // 200: { ok: true, requisicao_id, ... } ou { ok: true, duplicado: true, ... }
  }

  // Rota não encontrada
  return json(
    {
      error: 'not_found',
      message: `Rota não encontrada: ${req.method} ${url.pathname}`,
      rotas_validas: [
        'GET  /pdv-movimentacao/etiqueta/:uid',
        'POST /pdv-movimentacao/entrada',
        'POST /pdv-movimentacao/saida',
        'POST /pdv-movimentacao/requisicao',
      ],
    },
    404,
  )
}

// ─── Bootstrap ───────────────────────────────────────────────────────────────

const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? ''
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''

serve(async (req: Request) => {
  // OPTIONS pre-flight (CORS)
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: CORS_HEADERS })
  }

  // Service role client — bypassa RLS (segurança via RPC SECURITY DEFINER)
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY)

  return handler(req, supabase)
})

