// ════════════════════════════════════════════════════════════════
// handler — testes com mock de supabase client (sem rede)
// ════════════════════════════════════════════════════════════════

/** Mock de supabase que retorna a chave como válida para as RPCs. */
// deno-lint-ignore no-explicit-any
function mockSupabaseValido(lojaIds: number[] = [2, 3]): any {
  return {
    rpc: (name: string) => {
      if (name === 'validar_pdv_api_key') {
        return Promise.resolve({
          data: { ok: true, api_key_id: 'uuid-abc', loja_ids: lojaIds },
          error: null,
        })
      }
      if (name === 'consultar_etiqueta_pdv') {
        return Promise.resolve({
          data: { ok: true, etiqueta: { uid: 'TEST-UID' }, vencido: false },
          error: null,
        })
      }
      if (name === 'movimentar_lote_pdv') {
        return Promise.resolve({
          data: { ok: true, processados: 1, falhas: 0, resultados: [] },
          error: null,
        })
      }
      if (name === 'criar_requisicao_pdv') {
        return Promise.resolve({
          data: {
            ok: true,
            requisicao_id: 42,
            loja_solicitante: 'Momma Asa Sul',
            itens_inseridos: 2,
            data_recebimento: '2026-06-25',
          },
          error: null,
        })
      }
      return Promise.resolve({ data: null, error: null })
    },
  }
}

/** Mock com chave inválida. */
// deno-lint-ignore no-explicit-any
function mockSupabaseInvalido(): any {
  return {
    rpc: () => Promise.resolve({ data: { ok: false }, error: null }),
  }
}

// ── Ausência de x-api-key → 401 ──────────────────────────────────────────────
Deno.test('handler: sem x-api-key → 401 missing_api_key', async () => {
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/etiqueta/X',
    { method: 'GET' },
  )
  const res = await handler(req, {} as unknown)
  assertEquals(res.status, 401)
  const body = await res.json()
  assertEquals(body.error, 'missing_api_key')
})

// ── API key inválida → 401 unauthorized ──────────────────────────────────────
Deno.test('handler: api-key inválida → 401 unauthorized', async () => {
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/entrada',
    {
      method: 'POST',
      headers: { 'x-api-key': 'pdvk_invalida', 'Content-Type': 'application/json' },
      body: JSON.stringify({ loja_id: 2, uids: ['A'] }),
    },
  )
  const res = await handler(req, mockSupabaseInvalido())
  assertEquals(res.status, 401)
  const body = await res.json()
  assertEquals(body.error, 'unauthorized')
})

