// ── POST /entrada com uids vazio → 400 ───────────────────────────────────────
Deno.test('handler: POST /entrada com uids=[] → 400 uids_required', async () => {
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/entrada',
