        )
        .in('status', selected)
        .order('created_at', { ascending: false });

      if (error) throw error;
      const result = (reqs as any[]) || [];

      let filtered = result;
      if (lojaFilter !== 'todas') {
        const lojaName = (() => {
          const found = stores.find((s) => String(s.id) === String(lojaFilter));
          return found?.name || '';
        })();
        filtered = filtered.filter((r) => r.loja_solicitante === lojaName);
      }

