  IF p_itens IS NOT NULL THEN
    FOR v_item IN SELECT jsonb_array_elements(p_itens) LOOP
      v_nome := COALESCE(NULLIF(TRIM(v_item->>'nome_produto'), ''), NULL);
      IF v_nome IS NULL THEN
        CONTINUE;
      END IF;
      v_qtd_solicitada := COALESCE((v_item->>'quantidade_solicitada')::INT, 0);
      v_qtd_enviada := COALESCE(v_item->>'quantidade_enviada', '');
      v_obs := COALESCE(v_item->>'observacao', '');
      v_ordem := COALESCE((v_item->>'ordem')::INT, 0);
      v_category := COALESCE(v_item->>'category', NULL);
      v_produto_id := COALESCE((v_item->>'produto_id')::INT, NULL);
      -- Novo: unidade_medida do item. Default 'cx' se nao vier.
      v_unidade := COALESCE(NULLIF(TRIM(v_item->>'unidade_medida'), ''), 'cx');

      INSERT INTO public.requisicoes_itens (
        requisicao_id, nome_produto, quantidade_solicitada, quantidade_enviada,
        observacao, ordem, category, produto_id, unidade_medida
      ) VALUES (
        v_requisicao_id, v_nome, v_qtd_solicitada, v_qtd_enviada, v_obs, v_ordem, v_category, v_produto_id, v_unidade
      );
    END LOOP;
  END IF;

  RETURN v_requisicao_id;
END;
